<script setup lang="ts">
import { computed, reactive } from 'vue'
import { app, gs, act, close } from '../session'
import { ABILITIES, ABILITY_NAME, SKILL_NAME, signed, type Ability, type Skill } from '../rules/base'
import { availableSpells, sheet, type Hero } from '../rules/hero'
import { spellsFor } from '../rules/spells'
import { STYLES } from '../rules/classes'
import Modal from './Modal.vue'
const h = computed(() => gs.value!.chars[app.seat]); const next = computed(() => ({ ...(JSON.parse(JSON.stringify(h.value)) as Hero), level: h.value.level + 1 })); const A = computed(() => sheet(h.value)), B = computed(() => sheet(next.value)); const C = computed(() => A.value.cls); const feats = computed(() => C.value.features.filter(f => f.lv === h.value.level + 1 && !f.id.startsWith('asi'))); const asi = computed(() => C.value.features.some(f => f.id === 'asi' + (h.value.level + 1))), style = computed(() => C.value.style === h.value.level + 1 && !h.value.style), exp = computed(() => feats.value.some(f => f.id === 'expertise') || (h.value.cls === 'rogue' && h.value.level + 1 === 6)); const nC = computed(() => Math.max(0, B.value.cantripMax - h.value.cantrips.length)), nK = computed(() => B.value.knownMax ? Math.max(0, B.value.knownMax - h.value.known.length) : 0)
const c = reactive({ asi: [] as Ability[], learn: [] as string[], cantrip: [] as string[], expertise: [] as Skill[], style: '' }); const addA = (a: Ability) => { if (c.asi.length >= 2) c.asi.shift(); if (A.value.score[a] + c.asi.filter(x => x === a).length < 20) c.asi.push(a) }; const tog = (l: any[], id: any, n: number) => { const i = l.indexOf(id); if (i >= 0) l.splice(i, 1); else { if (l.length >= n) l.shift(); l.push(id) } }; const spells = computed(() => availableSpells(B.value).filter(s => !h.value.known.includes(s.id)).sort((a, b) => b.lv - a.lv)), cants = computed(() => spellsFor(h.value.cls, 0).filter(s => !h.value.cantrips.includes(s.id)))
const done = async () => { const r = await act({ k: 'level', c: JSON.parse(JSON.stringify(c)) }, app.seat); if (r.ok) close() }
</script>
<template><Modal :title="`${h.name} reaches level ${h.level + 1}`" vel icon="upgrade" :width="720"><div class="row wrap" style="gap:26px;margin-bottom:6px"><span><b class="n1">+{{ Math.max(1, B.max - A.max) }}</b> hit points</span><span v-if="B.prof > A.prof"><b class="n1">{{ signed(B.prof) }}</b> proficiency</span><span v-if="B.nAttacks > A.nAttacks"><b class="n1">{{ B.nAttacks }}</b> attacks</span><span v-if="B.slots.length > A.slots.length"><b class="n1">Level {{ B.slots.length }}</b> spells</span></div><div v-for="f in feats" :key="f.id" class="ft"><b>{{ f.name }}.</b> {{ f.text }}</div>
  <template v-if="asi"><span class="cap">Raise abilities, two points</span><div class="chips"><button v-for="a in ABILITIES" :key="a" class="chip" :class="{ on: c.asi.includes(a) }" @click="addA(a)">{{ ABILITY_NAME[a] }} {{ A.score[a] }}<b v-if="c.asi.includes(a)">+{{ c.asi.filter(x => x === a).length }}</b></button></div></template><template v-if="style"><span class="cap">Fighting style</span><div class="chips"><button v-for="s in STYLES" :key="s.id" class="chip" :class="{ on: c.style === s.id }" v-tip="s.text" @click="c.style = s.id">{{ s.name }}</button></div></template><template v-if="exp"><span class="cap">Expertise in two skills</span><div class="chips"><button v-for="s in h.skills.filter(x => !h.expertise.includes(x))" :key="s" class="chip s" :class="{ on: c.expertise.includes(s) }" @click="tog(c.expertise, s, 2)">{{ SKILL_NAME[s] }}</button></div></template>
  <template v-if="nC"><span class="cap">New cantrips, {{ c.cantrip.length }} of {{ nC }}</span><div class="sp"><button v-for="s in cants" :key="s.id" :class="{ on: c.cantrip.includes(s.id) }" @click="tog(c.cantrip, s.id, nC)"><b>{{ s.name }}</b><small>{{ s.text }}</small></button></div></template><template v-if="nK"><span class="cap">New spells, {{ c.learn.length }} of {{ nK }}</span><div class="sp"><button v-for="s in spells" :key="s.id" :class="{ on: c.learn.includes(s.id) }" @click="tog(c.learn, s.id, nK)"><b>{{ s.name }} <i>{{ s.lv }}</i></b><small>{{ s.text }}</small></button></div></template>
  <template #foot><span class="grow muted tiny">Anything left open is chosen for you.</span><button class="btn primary big" @click="done">Take the level</button></template></Modal></template>
<style scoped>.n1{font:800 34px/1 var(--serif)}.ft{margin-bottom:7px}.sp{display:grid;grid-template-columns:1fr 1fr;gap:0 20px;max-height:280px;overflow:auto}.sp button{padding:7px 9px;border-bottom:1px solid var(--line2)}.sp button:hover{background:var(--paper2)}.sp .on{background:var(--ink)!important;color:var(--paper)}.sp .on small{color:#c9ced4}.sp b{display:block;font:700 19px/1.1 var(--serif)}.sp small{display:block;font-size:15px;line-height:1.25;color:var(--ink2)}.sp i{font:400 15px var(--ui);font-style:normal}@media(max-width:640px){.sp{grid-template-columns:1fr}}</style>
